#!/usr/bin/env python3
"""The test_story_run_refusals tests were split (TD-11c): the parts hold the checks and story_run_refusals_common the shared helpers.
This module re-exports the names other tests import under the old name. It holds no check of its own: the canon
runs each part as its own process. `python -B test_story_run_refusals.py --all` runs the parts one after the other.
"""
# split-shim: generated by tools/test_split.py
import subprocess
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from story_run_refusals_common import (  # noqa: E402,F401
    RES_DISPATCH,
    RES_PLAIN,
    git_fixture,
    res_driver,
    res_errors,
    res_fixture,
)

# the re-export is the point of this module: naming it in __all__ keeps it
__all__ = ["RES_DISPATCH", "RES_PLAIN", "git_fixture", "res_driver", "res_errors", "res_fixture"]

PARTS = ("test_story_run_refusals_core", "test_story_run_refusals_sources", "test_story_run_refusals_resume", "test_story_run_refusals_t667_c21", "test_story_run_refusals_cc", "test_story_run_refusals_c24_n5")


def main() -> int:
    if "--all" not in sys.argv[1:]:
        print("test_story_run_refusals.py: no checks of its own; they are in " + ", ".join(p + ".py" for p in PARTS))
        return 0
    here = Path(__file__).resolve().parent
    code = 0
    for part in PARTS:
        code = subprocess.run([sys.executable, "-B", str(here / (part + ".py"))]).returncode or code
    return code


if __name__ == "__main__":
    sys.exit(main())
